          </SelectContent>
        </Select>
      </DialogFormField>

      <DialogFormField id="applyToAllMarks" label="Apply Marks to All Students">
        <div className="flex gap-2">
          <Input
            id="applyToAllMarks"
            type="number"
            min="0"
            value={applyToAllMarks}
