  );
}

"use client";

import React, { useEffect, useState } from "react";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Award } from "lucide-react";
import { EligibleStudent } from "@/services/student.service";
import { toast } from "sonner";
import {
  CourseInstructorData,
  getEligibleCourseInstructorsForCertificate,
} from "@/services/course-instructor.service";
import { useRequestCertificateForStudent } from "@/hooks/api/student.hooks";
import { selectInputValueOnFocus } from "@/lib/select-input-on-focus";
import {
  DialogFormField,
  DialogStateMessage,
  FormDialog,
} from "@/components/shared/dialog";

interface RequestCertificateModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  student: EligibleStudent;
  courseInstructors: CourseInstructorData[];
  onSuccess: () => void;
}

export default function RequestCertificateModal({
  open,
  onOpenChange,
  student,
  onSuccess,
}: RequestCertificateModalProps) {
  const [formData, setFormData] = useState({
    marksObtained: "",
    courseInstructorId: "",
  });
  const [eligibleInstructors, setEligibleInstructors] = useState<CourseInstructorData[]>([]);
  const [isLoadingInstructors, setIsLoadingInstructors] = useState(false);
  const requestCert = useRequestCertificateForStudent();

  useEffect(() => {
    let cancelled = false;
    async function loadEligible() {
      if (!open || !student.levelId) return;
      setIsLoadingInstructors(true);
      try {
        const rows = await getEligibleCourseInstructorsForCertificate(
          [student.levelId],
          student.programId ?? undefined,
        );
        if (!cancelled) setEligibleInstructors(rows);
      } catch (error) {
        if (!cancelled) {
          setEligibleInstructors([]);
          console.error("Error loading eligible course instructors:", error);
        }
      } finally {
        if (!cancelled) setIsLoadingInstructors(false);
      }
    }
    void loadEligible();
    return () => {
      cancelled = true;
    };
  }, [open, student.levelId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.marksObtained || !formData.courseInstructorId) {
      toast.error("Please fill in all required fields");
      return;
    }

    const marksObtained = parseInt(formData.marksObtained, 10);

    if (marksObtained < 0) {
      toast.error("Invalid marks: marks obtained must be non-negative");
      return;
    }

    if (!student.programId || !student.levelId) {
      toast.error("Student program or level is missing. Refresh and try again.");
      return;
    }

    try {
      await requestCert.mutateAsync({
        studentId: student.id,
        programId: student.programId,
        levelId: student.levelId,
        marksObtained,
        courseInstructorId: parseInt(formData.courseInstructorId, 10),
      });

      toast.success("Certificate request created successfully");

      setFormData({
        marksObtained: "",
        courseInstructorId: "",
      });

      onSuccess();
    } catch (error) {
      console.error("Error creating certificate request:", error);
      toast.error("Failed to create certificate request. Please try again.");
    }
  };

  const isLoading = requestCert.isPending;

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const selectedInstructor = eligibleInstructors.find(
    (ci) => ci.id.toString() === formData.courseInstructorId
  );

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      size="sm"
      title="Request Certificate"
      description={`Create a certificate request for ${student.name} (Roll No: ${student.rollNo})`}
      headerIcon={Award}
      onSubmit={handleSubmit}
      isSubmitting={isLoading}
      canSubmit={!isLoadingInstructors && eligibleInstructors.length > 0}
      submitLabel="Create Request"
      cancelLabel="Cancel"
    >
      <DialogFormField
        id="courseInstructor"
        label="Course Instructor"
        required
      >
        <Select
          value={formData.courseInstructorId}
          onValueChange={(value) =>
            handleInputChange("courseInstructorId", value)
          }
        >
          <SelectTrigger id="courseInstructor">
            <SelectValue placeholder="Select course instructor" />
          </SelectTrigger>
          <SelectContent>
            {isLoadingInstructors ? (
              <SelectItem value="loading" disabled>
                Loading eligible instructors...
              </SelectItem>
            ) : eligibleInstructors.length === 0 ? (
              <SelectItem value="none" disabled>
                No eligible instructors found for this level
              </SelectItem>
            ) : (
              eligibleInstructors.map((instructor) => (
                <SelectItem
                  key={instructor.id}
                  value={instructor.id.toString()}
                >
                  {instructor.name} ({instructor.instructorId})
                </SelectItem>
              ))
            )}
          </SelectContent>
        </Select>
      </DialogFormField>

      <DialogFormField
        id="marksObtained"
        label="Marks Obtained"
        required
      >
        <Input
          id="marksObtained"
          type="number"
          min="0"
          value={formData.marksObtained}
          onChange={(e) => handleInputChange("marksObtained", e.target.value)}
          onFocus={selectInputValueOnFocus}
          placeholder="e.g., 85"
          required
        />
      </DialogFormField>

      {selectedInstructor && (
        <DialogStateMessage
          tone="success"
          title="Selected Instructor"
          description={`${selectedInstructor.name} (${selectedInstructor.instructorId})`}
        />
      )}
    </FormDialog>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Award, Download, Loader2 } from "lucide-react";
import {
  getStudentCertificates,
  getFranchiseeCertificatePdfUrl,
  StudentCertificate,
} from "@/services/student.service";
import { toast } from "sonner";

interface StudentCertificatesModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  studentId: number;
  studentName?: string;
  certificateId?: number;
}

export default function StudentCertificatesModal({
  open,
  onOpenChange,
  studentId,
  studentName,
  certificateId,
}: StudentCertificatesModalProps) {
  const [certificates, setCertificates] = useState<StudentCertificate[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!open || !studentId) return;

    let cancelled = false;
    setIsLoading(true);

    getStudentCertificates(studentId)
      .then((response) => {
        if (cancelled) return;
        const certs = response.result || [];
        const filtered = certificateId
          ? certs.filter((cert) => cert.id === certificateId)
          : certs;
        setCertificates(filtered);
      })
      .catch((error) => {
        if (cancelled) return;
        console.error("Error loading certificates:", error);
        toast.error("Failed to load certificates");
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [open, studentId, certificateId]);

  const getStatusColor = (_status: string) =>
    "bg-primary/10 text-primary border-primary/20";

  const formatDate = (date?: string) => {
    if (!date) return "";
    return new Date(date).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  };

  const getTotalMarks = (certificate: StudentCertificate) =>
    certificate.totalMarks || certificate.levelTotalMarks || 0;

  const handleDownload = (certificate: StudentCertificate) => {
    const url = getFranchiseeCertificatePdfUrl(certificate.id);
    window.open(url, "_blank");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full max-w-2xl max-h-[85vh] overflow-y-auto overflow-x-hidden">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Award className="h-5 w-5 text-primary" />
            View Certificates
          </DialogTitle>
          <DialogDescription>
            {isLoading
              ? "Loading certificate records"
              : certificates.length === 0
              ? `No certificates found for ${studentName || "this student"}`
              : `${studentName || certificates[0]?.studentName || "Student"} — ${
                  certificateId ? "1 certificate" : `${certificates.length} total`
                }`}
          </DialogDescription>
        </DialogHeader>

        {isLoading ? (
          <div className="flex items-center justify-center py-10">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : certificates.length === 0 ? (
          <DialogFooter>
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Close
            </Button>
          </DialogFooter>
        ) : (
          <>
            <div className="space-y-2">
              {certificates.map((certificate) => {
                const hasPdf = certificate.status === "Issued";
                const totalMarks = getTotalMarks(certificate);
                const requestedDate = formatDate(certificate.requestDate);
                const issueDate = formatDate(certificate.issueDate);

                return (
                  <div
                    key={certificate.id}
                    className="flex items-center gap-3 rounded-lg border bg-card px-4 py-3"
                  >
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <h3 className="truncate text-sm font-semibold text-card-foreground">
                          {certificate.certificateLevel}
                        </h3>
                        <Badge
                          className={`${getStatusColor(
                            certificate.status,
                          )} h-5 rounded-full border px-2 text-[10px] font-medium`}
                        >
                          {certificate.status}
                        </Badge>
                      </div>
                      <div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground">
                        <span className="font-medium text-card-foreground">
                          {certificate.marksObtained}/{totalMarks}
                        </span>
                        <span>{certificate.instructorName}</span>
                        <span>
                          {issueDate || (requestedDate && `Requested ${requestedDate}`)}
                        </span>
                      </div>
                    </div>
                    <Button
                      variant="outline"
                      size="icon"
                      disabled={!hasPdf}
                      onClick={() => handleDownload(certificate)}
                      title={hasPdf ? "Download PDF" : "PDF not yet available"}
                      aria-label={hasPdf ? "Download PDF" : "PDF not yet available"}
                      className="h-8 w-8 shrink-0 rounded-md"
                    >
                      <Download className="h-4 w-4" />
                    </Button>
                  </div>
                );
              })}
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => onOpenChange(false)}>
                Close
              </Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

