"use client";

import React, { useState, useEffect } from "react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Loader2, AlertCircle } from "lucide-react";
import {
  requestAdditionalTraining,
  RequestAdditionalTrainingRequest,
  getAvailableTrainingLevelsForCI,
  type AvailableNextTrainingLevelCounts,
} from "@/services/course-instructor.service";
import { toast } from "sonner";
import { getUserFriendlyMessage } from "@/lib/error-utils";
import {
  AppDialog,
  DialogFormField,
  FormDialog,
} from "@/components/shared/dialog";

interface RequestTrainingModalProps {
  isOpen: boolean;
  onClose: () => void;
  instructorId: number;
  instructorName: string;
  onSuccess?: () => void;
}

function levelLabel(n: number) {
  return `${n} level${n === 1 ? "" : "s"}`;
}

export function RequestTrainingModal({
  isOpen,
  onClose,
  instructorId,
  instructorName,
  onSuccess,
}: RequestTrainingModalProps) {
  const [counts, setCounts] = useState<AvailableNextTrainingLevelCounts | null>(
    null,
  );
  const [scope, setScope] = useState<"half" | "all">("half");
  const [loading, setLoading] = useState(false);
  const [loadingLevels, setLoadingLevels] = useState(true);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    if (isOpen) {
      loadData();
    } else {
      setScope("half");
      setCounts(null);
      setError(null);
    }
  }, [isOpen, instructorId]);

  const loadData = async () => {
    try {
      setLoadingLevels(true);
      setError(null);

      const data = await getAvailableTrainingLevelsForCI(instructorId);
      setCounts(data);
      if (data.totalNextLevels <= 0) {
        setScope("half");
      } else if (data.halfOfAvailableCount === data.allAvailableCount) {
        setScope("all");
      } else {
        setScope("half");
      }
    } catch (err: any) {
      setError(getUserFriendlyMessage(err, "Failed to load training options"));
    } finally {
      setLoadingLevels(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!counts || counts.totalNextLevels === 0) return;

    setLoading(true);
    setError(null);

    try {
      const requestData: RequestAdditionalTrainingRequest = { scope };

      await requestAdditionalTraining(instructorId, requestData);

      toast.success("Training request submitted successfully");

      onSuccess?.();
      onClose();
    } catch (err: any) {
      setError(getUserFriendlyMessage(err, "Failed to submit training request"));
    } finally {
      setLoading(false);
    }
  };

  const hasLevels = counts != null && counts.totalNextLevels > 0;
  const halfEqualsAll =
    counts != null &&
    counts.halfOfAvailableCount === counts.allAvailableCount;
  const selectDisabled = hasLevels && halfEqualsAll;

  if (loadingLevels) {
    return (
      <AppDialog open={isOpen} onOpenChange={onClose} size="sm">
        <div className="flex items-center justify-center py-8">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      </AppDialog>
    );
  }

  if (error && !counts) {
    return (
      <AppDialog open={isOpen} onOpenChange={onClose} size="sm">
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      </AppDialog>
    );
  }

  return (
    <FormDialog
      open={isOpen}
      onOpenChange={onClose}
      size="sm"
      title="Request additional training"
      description={instructorName}
      onSubmit={handleSubmit}
      isSubmitting={loading}
      canSubmit={Boolean(hasLevels)}
      submitLabel="Submit request"
    >
      {!hasLevels ? (
        <p className="text-sm text-muted-foreground">
          No further levels are available for this instructor.
        </p>
      ) : (
        <DialogFormField
          id="training-scope"
          label={
            <span className="flex flex-wrap items-baseline gap-x-2">
              Levels to request
              <span className="text-sm text-muted-foreground font-normal">
                ({levelLabel(counts!.totalNextLevels)})
              </span>
            </span>
          }
        >
          <Select
            value={scope}
            onValueChange={(v) => setScope(v as "half" | "all")}
            disabled={selectDisabled}
          >
            <SelectTrigger id="training-scope" className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {halfEqualsAll ? (
                <SelectItem value="all">
                  {levelLabel(counts!.allAvailableCount)}
                </SelectItem>
              ) : (
                <>
                  <SelectItem value="half">
                    {levelLabel(counts!.halfOfAvailableCount)}
                  </SelectItem>
                  <SelectItem value="all">
                    {levelLabel(counts!.allAvailableCount)}
                  </SelectItem>
                </>
              )}
            </SelectContent>
          </Select>
        </DialogFormField>
      )}

      {error && counts && (
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
    </FormDialog>
  );
}

"use client";

import React, { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { StatusBadge } from "@/components/shared";
import { Edit, Trash2 } from "lucide-react";
import { DataTable } from "@/components/shared";
import type {
  DataTableColumn,
  DataTableSortOption,
} from "@/components/shared";
import { TrainingCourseInstructorData } from "@/services/course-instructor.service";
import TrainingCourseInstructorDetails from "./TrainingCourseInstructorDetails";

interface TrainingCourseInstructorsTableProps {
  courseInstructors?: TrainingCourseInstructorData[];
  onCourseInstructorUpdate?: (
    updatedCourseInstructor: TrainingCourseInstructorData
  ) => void;
  onCourseInstructorDelete?: (courseInstructorId: string) => void;
  onCourseInstructorEdit?: (
    courseInstructor: TrainingCourseInstructorData
  ) => void;
}

export default function TrainingCourseInstructorsTable({
  courseInstructors,
  onCourseInstructorUpdate,
  onCourseInstructorDelete,
  onCourseInstructorEdit,
}: TrainingCourseInstructorsTableProps) {
  const [searchTerm, setSearchTerm] = useState("");
  const [sortBy, setSortBy] = useState<"name" | "amount">(
    "name"
  );
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  // Use the course instructors directly since they're already filtered by the API
  const trainingCourseInstructors = courseInstructors || [];

  // Filter and sort data
  const filteredData = useMemo(() => {
    if (!trainingCourseInstructors) {
      return [];
    }

    let filtered = trainingCourseInstructors.filter((courseInstructor) => {
      const matchesSearch =
        courseInstructor.name
          .toLowerCase()
          .includes(searchTerm.toLowerCase()) ||
        courseInstructor.instructorId
          .toLowerCase()
          .includes(searchTerm.toLowerCase()) ||
        (courseInstructor.trainingLevelName &&
          courseInstructor.trainingLevelName
            .toLowerCase()
            .includes(searchTerm.toLowerCase())) ||
        (courseInstructor.additionalDetails &&
          courseInstructor.additionalDetails
            .toLowerCase()
            .includes(searchTerm.toLowerCase()));

      return matchesSearch;
    });

    // Sort the filtered data
    filtered.sort((a, b) => {
      let comparison = 0;

      switch (sortBy) {
        case "name":
          comparison = a.name.localeCompare(b.name);
          break;
        case "amount":
          comparison = (a.amount ?? 0) - (b.amount ?? 0);
          break;
        default:
          comparison = 0;
      }

      return sortOrder === "asc" ? comparison : -comparison;
    });

    return filtered;
  }, [
    trainingCourseInstructors,
    searchTerm,
    sortBy,
    sortOrder,
  ]);

  // Paginate data
  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(startIndex, startIndex + itemsPerPage);
  }, [filteredData, currentPage]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  // Helper function to format currency
  const formatCurrency = (amount: number): string => {
    return new Intl.NumberFormat("en-IN", {
      style: "currency",
      currency: "INR",
      minimumFractionDigits: 0,
    }).format(amount);
  };

  // Table configuration
  const columns: DataTableColumn<TrainingCourseInstructorData>[] = [
    {
      key: "courseInstructor",
      header: "Course Instructor",
      className: "w-[300px]",
    },
    {
      key: "trainingInfo",
      header: "Training Info",
      className: "text-center",
      render: (courseInstructor) => (
        <div className="space-y-1">
          {courseInstructor.trainingLevelName && (
            <Badge
              variant="outline"
              className="bg-primary/10 text-primary border-primary/20"
            >
              {courseInstructor.trainingLevelName}
            </Badge>
          )}
          <div className="text-sm text-muted-foreground">
            {courseInstructor.additionalDetails || "No details"}
          </div>
        </div>
      ),
    },
    {
      key: "paymentInfo",
      header: "Payment Info",
      className: "text-center",
      render: (courseInstructor) => (
        <div className="text-sm space-y-1">
          <div>
            <strong>Total:</strong>{" "}
            {formatCurrency(courseInstructor.amount ?? 0)}
          </div>
          {courseInstructor.paidAmount && (
            <div className="text-green-600">
              <strong>Paid:</strong>{" "}
              {formatCurrency(courseInstructor.paidAmount)}
            </div>
          )}
        </div>
      ),
    },
    {
      key: "status",
      header: "Status",
      className: "text-center",
      render: (courseInstructor) => (
        <StatusBadge label={courseInstructor.status} />
      ),
    },
    {
      key: "actions",
      header: "Actions",
      className: "text-center",
      render: (courseInstructor) => (
        <div className="flex items-center justify-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onCourseInstructorEdit?.(courseInstructor)}
          >
            <Edit className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() =>
              onCourseInstructorDelete?.(courseInstructor.id.toString())
            }
          >
            <Trash2 className="w-4 h-4" />
          </Button>
        </div>
      ),
    },
  ];

  const sortOptions: DataTableSortOption[] = [
    { value: "name", label: "Name" },
    { value: "amount", label: "Amount" },
  ];

  return (
    <DataTable
      data={paginatedData}
      loading={false}
      columns={columns}
      getRowId={(courseInstructor) => courseInstructor.id.toString()}
      renderMainCell={(courseInstructor) => (
        <div className="flex flex-col">
          <div className="font-medium text-card-foreground">
            {courseInstructor.name}
          </div>
          <div className="text-sm text-muted-foreground">
            {courseInstructor.instructorId}
          </div>
          <div className="text-xs text-primary font-medium">
            ID: {courseInstructor.id}
          </div>
        </div>
      )}
      renderExpandedContent={(courseInstructor) => (
        <TrainingCourseInstructorDetails
          courseInstructor={courseInstructor}
          onCourseInstructorUpdate={onCourseInstructorUpdate}
        />
      )}
      searchPlaceholder="Search training course instructors, instructor IDs, or names..."
      onSearchChange={setSearchTerm}
      sortOptions={sortOptions}
      defaultSortBy="name"
      defaultSortOrder="DESC"
      onSortChange={(newSortBy, newSortOrder) => {
        setSortBy(newSortBy as "name" | "amount");
        setSortOrder(newSortOrder.toLowerCase() as "asc" | "desc");
      }}
      pagination={{ total: filteredData.length, totalPages }}
      currentPage={currentPage}
      onPageChange={setCurrentPage}
      itemsPerPage={itemsPerPage}
      emptyMessage="No training course instructors found matching your criteria"
      resultsText={(count, total) =>
        `Showing ${count} of ${total} training course instructors`
      }
    />
  );
}

