            </div>

            {/* Right — dispatch-as panel is a fixed sidebar so it never gets clipped. */}
            <div className="flex min-h-0 min-w-0 shrink-0 flex-col overflow-y-auto px-4 py-4 sm:px-5 lg:w-[26rem]">
              <p className="text-sm font-semibold text-card-foreground">
                Dispatch as
              </p>
              <div className="mt-2 space-y-1 text-sm">
                <label className="flex cursor-pointer items-center gap-2">
                  <input
                    type="radio"
                    name="bulkDispatchFlowOrderMode"
                    checked={orderMode === "new"}
                    onChange={() => {
                      setOrderMode("new");
                      setSelectedOrderId(null);
                    }}
                    className="h-4 w-4 accent-primary"
                  />
                  Create as new dispatch order
                </label>
                <label className="flex cursor-pointer items-center gap-2">
                  <input
                    type="radio"
                    name="bulkDispatchFlowOrderMode"
                    checked={orderMode === "existing"}
                    onChange={() => setOrderMode("existing")}
                    className="h-4 w-4 accent-primary"
                  />
                  Add to existing order
                </label>
              </div>

              {orderMode === "existing" ? (
                <div className="mt-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border bg-white">
                  <div className="border-b bg-muted/30 px-3 py-2 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                    Eligible orders
                  </div>
                  <div className="min-h-0 flex-1 overflow-y-auto">
                    {isLoadingOrders ? (
                      <div className="flex items-center gap-2 px-3 py-6 text-sm text-gray-500">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Loading orders…
                      </div>
                    ) : eligibleOrders.length === 0 ? (
                      <div className="px-3 py-6 text-sm text-gray-500">
                        No eligible orders found for this franchise.
                      </div>
                    ) : (
                      eligibleOrders.map((order) => {
                        const selected = selectedOrderId === order.id;
                        return (
                          <label
                            key={order.id}
                            className={cn(
                              "flex cursor-pointer items-start gap-3 border-b px-3 py-2.5 text-sm transition-colors last:border-b-0",
                              selected ? "bg-primary/10" : "hover:bg-gray-50",
                            )}
                          >
                            <input
                              type="radio"
                              name="bulkDispatchFlowSelectedOrder"
                              checked={selected}
                              onChange={() => setSelectedOrderId(order.id)}
                              className="mt-0.5 h-4 w-4 shrink-0 accent-primary"
                            />
                            <div className="min-w-0 flex-1">
                              <div className="truncate font-medium text-gray-900">
                                {order.referenceId}
                              </div>
                              <div className="mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-xs text-muted-foreground">
                                <span className="truncate">
                                  {order.orderType}
                                </span>
                                <span>·</span>
                                <span>
                                  {order.shipment?.status ?? "Awaiting shipment"}
                                </span>
                                <span>·</span>
                                <span>
                                  {new Date(order.createdAt).toLocaleDateString()}
                                </span>
                              </div>
                            </div>
                          </label>
                        );
                      })
                    )}
                  </div>
                </div>
              ) : null}
            </div>
          </div>
        </AppDialogBody>
      )}

      <AppDialogFooter
        sticky
        tertiary={
          step === "preview"
            ? {
                label: "Back",
                onClick: handleBack,
                disabled: isSubmitting,
                variant: "outline",
              }
            : undefined
        }
        secondary={{
          label: "Cancel",
          onClick: () => onOpenChange(false),
        }}
        primary={
          step === "select"
            ? {
                label: isGenerating
                  ? "Generating…"
                  : `${generateLabel}${selectedIds.length > 0 ? ` (${selectedIds.length})` : ""}`,
                onClick: () => void handleGeneratePdf(),
                loading: isGenerating,
                disabled: isGenerateDisabled,
              }
            : {
                label: isSubmitting ? "Confirming…" : "Confirm dispatch",
                onClick: () => void handleConfirm(),
                loading: isSubmitting,
                disabled: isConfirmDisabled,
              }
        }
      />
    </AppDialog>
  );
}

"use client";

import { createContext, useContext, useState, useEffect, useCallback } from "react";
import { CIUser, getCIMe } from "@/services/ci-auth.service";
import { getCIAgreement, CIAgreementPhase } from "@/services/ci-training.service";

interface CIAuthContextValue {
  user: CIUser | null;
  loading: boolean;
  agreementPhase: CIAgreementPhase | null;
  refresh: () => Promise<void>;
  clear: () => void;
}

const CIAuthContext = createContext<CIAuthContextValue>({
  user: null,
  loading: true,
  agreementPhase: null,
  refresh: async () => {},
  clear: () => {},
});

export function CIAuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<CIUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [agreementPhase, setAgreementPhase] = useState<CIAgreementPhase | null>(null);

  const refresh = useCallback(async () => {
    try {
      const me = await getCIMe();
      setUser(me);
      const agreement = await getCIAgreement().catch(() => null);
      setAgreementPhase(agreement?.phase ?? null);
    } catch {
      setUser(null);
      setAgreementPhase(null);
    } finally {
      setLoading(false);
    }
  }, []);

  const clear = useCallback(() => {
    setUser(null);
    setAgreementPhase(null);
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return (
    <CIAuthContext.Provider value={{ user, loading, agreementPhase, refresh, clear }}>
      {children}
    </CIAuthContext.Provider>
  );
}

export function useCIAuth() {
  return useContext(CIAuthContext);
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { usePathname, useSearchParams } from "next/navigation";

/**
 * Tab state synced to a `?tab=` query param.
 *
 * Drives `tab` from local React state instead of `useSearchParams()` directly.
 * Reason: on Next.js 16 + React 19, calling `router.replace()` to update a
 * search param on a statically-renderable client page started via full HTTP
 * load (i.e. a browser reload) does not always trigger a re-render of the
 * `useSearchParams()` subscriber. The address bar would not update and the
 * controlled `<Tabs value={tab}>` would freeze on the old value, making the
 * tab buttons appear unresponsive even though Radix received the click.
 *
 * Local state + `window.history.replaceState` decouples the tab UI from the
 * router so a click always re-renders, while keeping the URL shareable and
 * keeping back/forward navigation in sync via the `useSearchParams` effect.
 */
export function useTabFromUrl<const TAllowed extends readonly string[]>(
  defaultTab: TAllowed[number],
  allowed: TAllowed,
) {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const resolveFromUrl = useCallback((): TAllowed[number] => {
    const raw = searchParams.get("tab");
    return raw && (allowed as readonly string[]).includes(raw)
      ? (raw as TAllowed[number])
      : defaultTab;
  }, [searchParams, allowed, defaultTab]);

  const [tab, setTabState] = useState<TAllowed[number]>(resolveFromUrl);

  // Sync URL → state for external URL changes (browser back/forward, links).
  // `window.history.replaceState` (used in setTab below) does not fire
  // popstate, so this effect only fires for genuine external navigation.
  useEffect(() => {
    setTabState(resolveFromUrl());
  }, [resolveFromUrl]);

  const setTab = useCallback(
    (value: string) => {
      const next = (allowed as readonly string[]).includes(value)
        ? (value as TAllowed[number])
        : defaultTab;
      setTabState(next);
      if (typeof window !== "undefined") {
        const params = new URLSearchParams(window.location.search);
        params.set("tab", next);
        window.history.replaceState(
          null,
          "",
          `${pathname}?${params.toString()}`,
        );
      }
    },
    [pathname, allowed, defaultTab],
  );

  return [tab, setTab] as const;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  applyRecomputedTotal,
  applyStartingKitQuantityScales,
  filterInvoicePreviewBySelection,
  mergeInstructorGroups,
  mergeStartingKitGroups,
  mergeStudentGroups,
  studentGroupsToBreakdowns,
} from "@/lib/invoice-preview-merge";
import {
  previewOrderInvoice,
  type InvoicePreview,
} from "@/services/order.service";

export interface StartingKitSelectionItem {
  streamId: number;
  quantity: number;
  tshirtItemId: number | null;
}

function emptyPreview(seed?: Partial<InvoicePreview>): InvoicePreview {
  return {
    franchiseId: seed?.franchiseId ?? "",
    programId: seed?.programId ?? 0,
    levelId: seed?.levelId ?? 0,
    isFirstLevel: seed?.isFirstLevel ?? false,
    students: [],
    lines: [],
    totalAmount: 0,
    studentGroups: [],
    startingKitGroups: [],
    instructorGroups: [],
  };
}

function mergeOnePreviewBlock(
  base: InvoicePreview,
  part: InvoicePreview,
): InvoicePreview {
  const studentGroups = mergeStudentGroups(
    base.studentGroups ?? [],
    part.studentGroups ?? [],
  );
  const instructorGroups = mergeInstructorGroups(
    base.instructorGroups ?? [],
    part.instructorGroups ?? [],
  );
  const startingKitGroups = mergeStartingKitGroups(
    base.startingKitGroups ?? [],
    part.startingKitGroups ?? [],
  );
  return applyRecomputedTotal({
    ...base,
    franchiseId: part.franchiseId ?? base.franchiseId,
    programId: part.programId ?? base.programId,
    levelId: part.levelId ?? base.levelId,
    isFirstLevel: part.isFirstLevel ?? base.isFirstLevel,
    studentGroups,
    instructorGroups,
    startingKitGroups,
    students: studentGroupsToBreakdowns(studentGroups),
    lines: [],
  });
}

export interface UseUnifiedInvoicePreviewArgs {
  open: boolean;
  hasSelection: boolean;
  selectedStudentIds: number[];
  selectedInstructorIds: number[];
  startingKitItems: StartingKitSelectionItem[];
  franchiseId?: string | number;
}

export interface UseUnifiedInvoicePreviewResult {
  preview: InvoicePreview | undefined;
  isLoading: boolean;
  isFetching: boolean;
  isError: boolean;
  error: Error | null;
  refetch: () => void;
}

export function useUnifiedInvoicePreview({
  open,
  hasSelection,
  selectedStudentIds,
  selectedInstructorIds,
  startingKitItems,
  franchiseId,
}: UseUnifiedInvoicePreviewArgs): UseUnifiedInvoicePreviewResult {
  // Franchisee JWT: server resolves franchise from token; `franchiseId` here is for admin-style calls only.
  const [preview, setPreview] = useState<InvoicePreview | null>(null);
  const [isFetching, setIsFetching] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [refetchTick, setRefetchTick] = useState(0);

  const genRef = useRef(0);
  const mergedRef = useRef<InvoicePreview | null>(null);

  const studentKey = useMemo(
    () => [...selectedStudentIds].sort((a, b) => a - b).join(","),
    [selectedStudentIds],
  );
  const instructorKey = useMemo(
    () => [...selectedInstructorIds].sort((a, b) => a - b).join(","),
    [selectedInstructorIds],
  );
  const kitKey = useMemo(
    () =>
      [...startingKitItems]
        .sort((a, b) => a.streamId - b.streamId)
        .map((i) => `${i.streamId}:${i.tshirtItemId ?? "none"}:${i.quantity}`)
        .join(","),
    [startingKitItems],
  );

  useEffect(() => {
    let cancelled = false;

    async function run() {
      if (!open || !hasSelection) {
        genRef.current += 1;
        mergedRef.current = null;
        setPreview(null);
        setError(null);
        setIsFetching(false);
        return;
      }

      const myGen = ++genRef.current;
      setIsFetching(true);
      setError(null);

      const studentSet = new Set(selectedStudentIds);
      const instructorSet = new Set(selectedInstructorIds);
      // Sum quantities per streamId — a stream may appear in multiple rows
      // (one per t-shirt selection), and downstream filter/scale operate on
      // the total quantity per stream group.
      const kitQtyByStreamId = new Map<number, number>();
      for (const i of startingKitItems) {
        kitQtyByStreamId.set(
          i.streamId,
          (kitQtyByStreamId.get(i.streamId) ?? 0) + i.quantity,
        );
      }

      let working: InvoicePreview | null = mergedRef.current;

      if (working != null) {
        working = filterInvoicePreviewBySelection(working, {
          studentIds: studentSet,
          instructorIds: instructorSet,
          kitQtyByStreamId,
        });
        working = applyStartingKitQuantityScales(working, kitQtyByStreamId);
      } else {
        working = emptyPreview();
      }

      const inStudentPreview = new Set(
        (working.studentGroups ?? []).map((g) => g.studentId),
      );
      const addedStudentIds = selectedStudentIds.filter(
        (id) => !inStudentPreview.has(id),
      );

      const inInstructorPreview = new Set(
        (working.instructorGroups ?? []).map((g) => g.instructorId),
      );
      const addedInstructorIds = selectedInstructorIds.filter(
        (id) => !inInstructorPreview.has(id),
      );

      // Always re-request the full kit block when kits change. Each group may
      // contain multiple t-shirt rows, and the per-(streamId, tshirtItemId)
      // dedupe would need to inspect all of `tshirtBreakdown` — the optimization
      // isn't worth the complexity; kit previews are cheap. (Note: the cached
      // kit groups in `working` get overlay-replaced by streamId during merge,
      // so freshly-fetched groups win.)
      const newKitPayload = startingKitItems;

      const dtoBase =
        franchiseId != null && franchiseId !== ""
          ? { franchiseId: String(franchiseId) }
          : {};

      const tasks: Promise<InvoicePreview>[] = [];
      if (addedStudentIds.length > 0) {
        tasks.push(
          previewOrderInvoice({
            ...dtoBase,
            studentIds: addedStudentIds,
          }),
        );
      }
      if (addedInstructorIds.length > 0) {
        tasks.push(
          previewOrderInvoice({
            ...dtoBase,
            instructorIds: addedInstructorIds,
          }),
        );
      }
      if (newKitPayload.length > 0) {
        tasks.push(
          previewOrderInvoice({
            ...dtoBase,
            startingKitItems: newKitPayload.map((i) => ({
              streamId: i.streamId,
              quantity: i.quantity,
              tshirtItemId: i.tshirtItemId,
            })),
          }),
        );
      }

      try {
        if (tasks.length > 0) {
          const parts = await Promise.all(tasks);
          if (cancelled || myGen !== genRef.current) return;
          let merged = working;
          for (const part of parts) {
            merged = mergeOnePreviewBlock(merged, part);
          }
          mergedRef.current = merged;
          setPreview(merged);
        } else {
          if (cancelled || myGen !== genRef.current) return;
          mergedRef.current = working;
          setPreview(working);
        }
      } catch (e) {
        if (cancelled || myGen !== genRef.current) return;
        setError(e instanceof Error ? e : new Error(String(e)));
      } finally {
        if (!cancelled && myGen === genRef.current) {
          setIsFetching(false);
        }
      }
    }

    void run();
    return () => {
      cancelled = true;
    };
  }, [
    open,
    hasSelection,
    studentKey,
    instructorKey,
    kitKey,
    franchiseId,
    refetchTick,
  ]);

  const refetch = useCallback(() => {
    mergedRef.current = null;
    setPreview(null);
    setError(null);
    setRefetchTick((t) => t + 1);
  }, []);

  const isLoading = Boolean(
    open && hasSelection && preview == null && !error && isFetching,
  );

  return {
    preview: preview ?? undefined,
    isLoading,
    isFetching,
    isError: error != null,
    error,
    refetch,
  };
}

